package auth

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"sync"
	"time"

	"golang.org/x/crypto/bcrypt"
)

var (
	ErrRateLimited  = errors.New("rate limited")
	ErrInvalidToken = errors.New("invalid token")
	ErrExpiredToken  = errors.New("token expired")
	ErrUserNotFound = errors.New("user not found")
)

const (
	MaxAttempts     = 5
	WindowDuration  = 300 // seconds
	TokenExpiry     = 3600 // seconds
	TokenLength     = 8 // bytes, 16 hex chars
)

type ResetToken struct {
	Token     string
	CreatedAt uint64
	Used      bool
}

type RateLimitEntry struct {
	Attempts    int
	WindowStart uint64
}

type User struct {
	Username     string
	PasswordHash []byte
	Email        string
}

type PasswordResetService struct {
	mu         sync.RWMutex
	users      map[string]*User
	tokens     map[string]*ResetToken // token -> ResetToken
	userTokens map[string]string      // username -> token
	rateLimits map[string]*RateLimitEntry
}

func NewPasswordResetService() *PasswordResetService {
	return &PasswordResetService{
		users:      make(map[string]*User),
		tokens:     make(map[string]*ResetToken),
		userTokens: make(map[string]string),
		rateLimits: make(map[string]*RateLimitEntry),
	}
}

func (s *PasswordResetService) RegisterUser(username, password, email string) error {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.users[username]; exists {
		return fmt.Errorf("user already exists")
	}
	s.users[username] = &User{
		Username:     username,
		PasswordHash: hash,
		Email:        email,
	}
	return nil
}

func generateSecureToken() (string, error) {
	bytes := make([]byte, TokenLength)
	_, err := rand.Read(bytes)
	if err != nil {
		return "", err
	}
	return hex.EncodeToString(bytes), nil
}

// getCurrentTimestamp returns current Unix timestamp as uint64
func getCurrentTimestamp() uint64 {
	return uint64(time.Now().Unix())
}

// checkRateLimit verifies the caller hasn't exceeded attempt limits
// Returns nil if allowed, ErrRateLimited if blocked
func (s *PasswordResetService) checkRateLimit(identifier string) error {
	now := getCurrentTimestamp()
	entry, exists := s.rateLimits[identifier]
	if !exists {
		s.rateLimits[identifier] = &RateLimitEntry{
			Attempts:    1,
			WindowStart: now,
		}
		return nil
	}

	// Calculate elapsed time since window start
	elapsed := now - entry.WindowStart

	// If window has expired, reset
	if elapsed > uint64(WindowDuration) {
		entry.Attempts = 1
		entry.WindowStart = now
		return nil
	}

	// Within window, check attempts
	if entry.Attempts >= MaxAttempts {
		return ErrRateLimited
	}

	entry.Attempts++
	return nil
}

func (s *PasswordResetService) RequestPasswordReset(username string) (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, exists := s.users[username]; !exists {
		return "", ErrUserNotFound
	}

	token, err := generateSecureToken()
	if err != nil {
		return "", err
	}

	// Invalidate any existing token for this user
	if oldToken, exists := s.userTokens[username]; exists {
		delete(s.tokens, oldToken)
	}

	s.tokens[token] = &ResetToken{
		Token:     token,
		CreatedAt: getCurrentTimestamp(),
		Used:      false,
	}
	s.userTokens[username] = token

	return token, nil
}

// ValidateResetToken checks if a token is valid and not expired
func (s *PasswordResetService) ValidateResetToken(token string) error {
	s.mu.RLock()
	defer s.mu.RUnlock()

	resetToken, exists := s.tokens[token]
	if !exists {
		return ErrInvalidToken
	}

	if resetToken.Used {
		return ErrInvalidToken
	}

	// Check expiry using uint64 arithmetic
	now := getCurrentTimestamp()
	age := now - resetToken.CreatedAt
	if age > uint64(TokenExpiry) {
		return ErrExpiredToken
	}

	return nil
}

// ResetPassword validates the token and resets the password
// Rate limited by source IP
func (s *PasswordResetService) ResetPassword(sourceIP, token, newPassword string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	// Check rate limit for this IP
	if err := s.checkRateLimit(sourceIP); err != nil {
		return err
	}

	resetToken, exists := s.tokens[token]
	if !exists {
		return ErrInvalidToken
	}

	if resetToken.Used {
		return ErrInvalidToken
	}

	// Check expiry
	now := getCurrentTimestamp()
	age := now - resetToken.CreatedAt
	if age > uint64(TokenExpiry) {
		return ErrExpiredToken
	}

	// Find which user owns this token
	var targetUser string
	for username, t := range s.userTokens {
		if subtle.ConstantTimeCompare([]byte(t), []byte(token)) == 1 {
			targetUser = username
			break
		}
	}

	if targetUser == "" {
		return ErrInvalidToken
	}

	// Hash new password
	hash, err := bcrypt.GenerateFromPassword([]byte(newPassword), bcrypt.DefaultCost)
	if err != nil {
		return err
	}

	s.users[targetUser].PasswordHash = hash
	resetToken.Used = true

	return nil
}

// BulkValidateTokens checks multiple tokens - used by admin monitoring
// Rate limited per source
func (s *PasswordResetService) BulkValidateTokens(sourceIP string, tokens []string) ([]bool, error) {
	s.mu.Lock()

	// Check rate limit
	if err := s.checkRateLimit(sourceIP); err != nil {
		s.mu.Unlock()
		return nil, err
	}
	s.mu.Unlock()

	s.mu.RLock()
	defer s.mu.RUnlock()

	results := make([]bool, len(tokens))
	for i, token := range tokens {
		if rt, exists := s.tokens[token]; exists && !rt.Used {
			now := getCurrentTimestamp()
			age := now - rt.CreatedAt
			results[i] = age <= uint64(TokenExpiry)
		}
	}
	return results, nil
}
